package com.tekwatt.reporting.service;
import com.fasterxml.jackson.databind.JsonNode;import com.tekwatt.reporting.dto.*;import com.tekwatt.reporting.entity.*;import com.tekwatt.reporting.repository.ReportRepository;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.UUID;import org.springframework.beans.factory.annotation.Value;import org.springframework.data.domain.*;import org.springframework.http.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.client.RestClient;import org.springframework.web.server.ResponseStatusException;
@Service @Transactional public class ReportingService {private final ReportRepository repository;private final RestClient analytics;private final CsvReportGenerator csv;private final HtmlReportGenerator html;private final PdfReportGenerator pdf;public ReportingService(ReportRepository repository,RestClient.Builder builder,CsvReportGenerator csv,HtmlReportGenerator html,PdfReportGenerator pdf,@Value("${tekwatt.analytics.base-url}")String baseUrl){this.repository=repository;analytics=builder.baseUrl(baseUrl).build();this.csv=csv;this.html=html;this.pdf=pdf;}public ReportResponse create(CreateReportRequest request){if(!request.from().isBefore(request.to()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"from must be before to");ReportFormat format=request.resolvedFormat();Report report=repository.save(new Report(request.tenantId(),request.reportType(),format,request.from(),request.to()));try{JsonNode data=fetch(request);String name=request.reportType().name().toLowerCase()+"-"+request.tenantId()+"-"+DateTimeFormatter.BASIC_ISO_DATE.withZone(ZoneOffset.UTC).format(request.from())+"."+format.extension();byte[] content=switch(format){case HTML->html.generate(request.reportType(),data);case PDF->pdf.generate(request.reportType(),data);case CSV->csv.generate(request.reportType(),data);};report.complete(name,content);}catch(Exception ex){report.fail(ex.getMessage());}return ReportResponse.from(repository.save(report));}private JsonNode fetch(CreateReportRequest r){if(r.reportType()==ReportType.OVERVIEW)return analytics.get().uri(uri->uri.path("/api/v1/analytics/overview").queryParam("tenantId",r.tenantId()).queryParam("from",r.from()).queryParam("to",r.to()).build()).retrieve().body(JsonNode.class);LocalDate from=LocalDate.ofInstant(r.from(),ZoneOffset.UTC);LocalDate to=LocalDate.ofInstant(r.to().minusNanos(1),ZoneOffset.UTC);return analytics.get().uri(uri->uri.path("/api/v1/analytics/daily").queryParam("tenantId",r.tenantId()).queryParam("from",from).queryParam("to",to).build()).retrieve().body(JsonNode.class);}@Transactional(readOnly=true)public Report getEntity(UUID id){return repository.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Report not found"));}@Transactional(readOnly=true)public ReportResponse get(UUID id){return ReportResponse.from(getEntity(id));}@Transactional(readOnly=true)public Page<ReportResponse> list(UUID tenantId,Pageable pageable){return repository.findByTenantIdOrderByCreatedAtDesc(tenantId,pageable).map(ReportResponse::from);}}
